"""Tensor-parallel linear layers (Megatron-style) implemented with PyTorch.

ColumnParallelLinear shards the weight along the output-feature dimension and
all_gathers the partial outputs along the last dimension.
RowParallelLinear shards the weight along the input-feature dimension, expects
an already-scattered input slice, and all_reduces the partial outputs.

Collectives are wrapped in autograd Functions so gradients flow correctly.
If no process group is initialized they degrade to no-ops (world_size == 1).
"""

import torch
import torch.distributed as dist

__all__ = ["ColumnParallelLinear", "RowParallelLinear"]


# --------------------------------------------------------------------------- #
# distributed helpers
# --------------------------------------------------------------------------- #
def _dist_ready():
    try:
        return dist.is_available() and dist.is_initialized()
    except Exception:
        return False


def _world_size():
    try:
        ws = dist.get_world_size()
    except Exception:
        return 1
    return 1 if not ws else int(ws)


def _rank():
    try:
        r = dist.get_rank()
    except Exception:
        return 0
    return 0 if not r else int(r)


def _raw_all_reduce(tensor):
    if not _dist_ready() or _world_size() == 1:
        return tensor
    tensor = tensor.contiguous()
    dist.all_reduce(tensor, op=dist.ReduceOp.SUM)
    return tensor


def _raw_all_gather(tensor):
    world_size = _world_size()
    if not _dist_ready() or world_size == 1:
        return tensor
    tensor = tensor.contiguous()
    gathered = [torch.empty_like(tensor) for _ in range(world_size)]
    dist.all_gather(gathered, tensor)
    gathered[_rank()] = tensor
    return torch.cat(gathered, dim=-1)


def _shard(tensor, dim, world_size, rank):
    """Return this rank's contiguous slice of ``tensor`` along ``dim``."""
    if world_size == 1:
        return tensor
    size = tensor.shape[dim]
    if size % world_size == 0:
        chunk = size // world_size
        start = rank * chunk
    else:  # uneven split: same policy as torch.chunk
        chunk = (size + world_size - 1) // world_size
        start = min(rank * chunk, size)
        chunk = min(chunk, size - start)
    return tensor.narrow(dim, start, chunk)


class _CopyToParallelRegion(torch.autograd.Function):
    """Identity forward, all_reduce backward (input is replicated on all ranks)."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return _raw_all_reduce(grad_output.clone())


class _GatherFromParallelRegion(torch.autograd.Function):
    """all_gather along last dim forward, take local slice backward."""

    @staticmethod
    def forward(ctx, x):
        return _raw_all_gather(x)

    @staticmethod
    def backward(ctx, grad_output):
        return _shard(grad_output, -1, _world_size(), _rank()).contiguous()


class _ReduceFromParallelRegion(torch.autograd.Function):
    """all_reduce forward, identity backward."""

    @staticmethod
    def forward(ctx, x):
        return _raw_all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


def _oriented_master_weight(master_weight, in_features, out_features):
    """Return master weight with torch.nn.Linear layout ``(out, in)``."""
    w = master_weight
    if not torch.is_tensor(w):
        w = torch.as_tensor(w)
    if w.dim() != 2:
        raise ValueError("master_weight must be a 2D tensor")
    if tuple(w.shape) == (out_features, in_features):
        return w
    if tuple(w.shape) == (in_features, out_features):
        return w.t()
    raise ValueError(
        "master_weight shape {} incompatible with in_features={}, "
        "out_features={}".format(tuple(w.shape), in_features, out_features)
    )


