# layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(torch.nn.Module):
    """Linear layer with the weight sharded along its output dimension.

    y = x @ W^T + b with W = [W_0; W_1; ...] split along output features.
    Each rank computes its own slice; the result is all_gathered along the last
    dimension so every rank returns the full output.
    """

    def __init__(self, in_features, out_features, bias=True, master_weight=None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()

        if master_weight is None:
            master_weight = torch.empty(out_features, in_features)
            torch.nn.init.xavier_normal_(master_weight)
        master_weight = _oriented_master_weight(master_weight, in_features, out_features)

        weight_shard = _shard(
            master_weight.detach(), 0, self.world_size, self.rank
        ).clone()
        self.output_size_per_partition = weight_shard.shape[0]
        self.input_size_per_partition = in_features
        self.weight = torch.nn.Parameter(weight_shard)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
            with torch.no_grad():
                self.bias.zero_()
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        input_parallel = _CopyToParallelRegion.apply(input_)
        output_parallel = torch.nn.functional.linear(
            input_parallel, self.weight, self.bias
        )
        return _GatherFromParallelRegion.apply(output_parallel)

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )


class RowParallelLinear(torch.nn.Module):
    """Linear layer with the weight sharded along its input dimension.

    forward() receives only this rank's slice of the input (already scattered
    along the last dimension). Partial outputs are all_reduced (summed) and the
    full bias is added afterwards.
    """

    def __init__(self, in_features, out_features, bias=True, master_weight=None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()

        if master_weight is None:
            master_weight = torch.empty(out_features, in_features)
            torch.nn.init.xavier_normal_(master_weight)
        master_weight = _oriented_master_weight(master_weight, in_features, out_features)

        weight_shard = _shard(
            master_weight.detach(), 1, self.world_size, self.rank
        ).clone()
        self.input_size_per_partition = weight_shard.shape[1]
        self.output_size_per_partition = out_features
        self.weight = torch.nn.Parameter(weight_shard)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
            with torch.no_grad():
                self.bias.zero_()
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        output_parallel = torch.nn.functional.linear(input_, self.weight)
        output = _ReduceFromParallelRegion.apply(output_parallel)
        if self.bias is not None:
            output = output + self.bias
        return output

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )
